  "lines": [
    {
      "id": "story.acts",
      "tiers": [
        {
          "id": "story.acts:t1",
          "title": "Сюжет выходит на мост",
          "phrase": "Ты выполнил обязательные базовые условия 3 актов истории. Бобёр за кулисами установил мост: сюжет может топать дальше.",
          "imagePrompt": "A small beaver stagehand with a canvas tool belt pushes a wooden bridge section into place on a miniature theater stage, one paw resting on a lever while a shy dragon puppet peeks through a partly opened curtain.",
          "fishMarkup": "[warm] Ты выполнил обязательные базовые условия 3 актов истории. [playful] Бобёр за кулисами установил мост: сюжет может топать дальше.",
          "audioText": "Ты выполнил обязательные базовые условия 3 актов истории. Бобёр за кулисами установил мост: сюжет может топать дальше."
        },
        {
          "id": "story.acts:t2",
          "title": "За рычагами сюжета",
          "phrase": "Уже в 10 актах истории ты выполнил обязательные базовые условия. Бобёр крутит рычаги, а ты двигаешь сюжет — без тебя дракон просто мебель.",
          "imagePrompt": "The same tool-belted beaver stands at a bank of levers, lifting a jointed wooden dragon over a rotating bridge set; taut control ropes converge around its paws as the compact stage becomes a busy storytelling machine.",
          "fishMarkup": "[confident] Уже в 10 актах истории ты выполнил обязательные базовые условия. [playful] Бобёр крутит рычаги, а ты двигаешь сюжет — без тебя дракон просто <emphasis>мебель</emphasis>.",
          "audioText": "Уже в 10 актах истории ты выполнил обязательные базовые условия. Бобёр крутит рычаги, а ты двигаешь сюжет — без тебя дракон просто мебель."
        },
        {
          "id": "story.acts:t3",
          "title": "Дракон с чайной начинкой",
          "phrase": "Ты выполнил обязательные базовые условия 30 актов истории. Дракон раскрыл пасть, а там — бобёр с чаем: у сюжета антракт.",
          "imagePrompt": "The same tool-belted beaver lounges with a teacup inside the open jaws of an enormous hinged stage dragon, its control levers still within reach; the dragon's folded wooden body fills the stage behind this tiny surprise operator.",
          "fishMarkup": "[triumphant] Ты выполнил обязательные базовые условия 30 актов истории. Дракон раскрыл пасть, <slow>а там —</slow> [playful] бобёр с чаем: у сюжета антракт.",
          "audioText": "Ты выполнил обязательные базовые условия 30 актов истории. Дракон раскрыл пасть, а там — бобёр с чаем: у сюжета антракт."
        }
      ]
    },
    {
      "id": "story.finale",
      "tiers": [
        {
          "id": "story.finale:t1",
          "title": "Титры на месте",
          "phrase": "Ты завершил исходный план тренировки с выбранным сценарием — это твой первый такой финал. Титры можно отпускать со смены.",
          "imagePrompt": "A small penguin projectionist in a plain waistcoat lifts a freshly rewound film reel from a hand-cranked projector, holding it with both flippers as the last loose strip curls neatly back onto the spool.",
          "fishMarkup": "[warm] Ты завершил исходный план тренировки с выбранным сценарием — это твой <emphasis>первый такой финал</emphasis>. [playful] Титры можно отпускать со смены.",
          "audioText": "Ты завершил исходный план тренировки с выбранным сценарием — это твой первый такой финал. Титры можно отпускать со смены."
        },
        {
          "id": "story.finale:t2",
          "title": "Катушки знают порядок",
          "phrase": "Ты уже 5 раз завершил исходный план тренировки с выбранным сценарием. Катушки строятся в очередь: знают, кто здесь ведёт сюжет.",
          "imagePrompt": "The same waistcoated penguin projectionist guides a row of completed film reels into a compact rack beside its projector, using a long winding handle as if conducting a very orderly mechanical orchestra.",
          "fishMarkup": "[confident] Ты уже <emphasis>5 раз</emphasis> завершил исходный план тренировки с выбранным сценарием. [playful] Катушки строятся в очередь: знают, кто здесь ведёт сюжет.",
          "audioText": "Ты уже 5 раз завершил исходный план тренировки с выбранным сценарием. Катушки строятся в очередь: знают, кто здесь ведёт сюжет."
        },
        {
          "id": "story.finale:t3",
          "title": "Проектор тоже артист",
          "phrase": "Ты уже 15 раз завершил исходный план тренировки с выбранным сценарием. Проектор показал титры и… сам вышел на поклон.",
          "imagePrompt": "The same waistcoated penguin projectionist bows beside a movie projector standing on its own articulated legs; the projector bends its lens in an exaggerated bow while a broad loop of film curls behind the unlikely performing duo.",
          "fishMarkup": "[triumphant] Ты уже <emphasis>15 раз</emphasis> завершил исходный план тренировки с выбранным сценарием. Проектор показал титры и… <slow>сам вышел на поклон.</slow>",
          "audioText": "Ты уже 15 раз завершил исходный план тренировки с выбранным сценарием. Проектор показал титры и… сам вышел на поклон."
        }
      ]
    }
  ]
}
